#root #keysmodal #keysreset{ min-height:var(--sp-5); font-size:var(--fs-body); }

/* v28.xx (cw-setone) critic c-31 (Settings 2, P0): "two nav systems on one screen ... delete one". The Game and Send play data tabs beside the title are gone while you are on the Game page: Send play data is the last chip of the one section strip (same chip, same page), and the title row shows the two tabs only on the Send play data page, so the way back is still there. Keys: the row under the pointer gets the raised fill and the amber bar like Settings. */
#root #settingsmodal:not(.recmode) #settabs{ visibility:hidden; pointer-events:none; }
#root #setlist .setjump button[data-go]{ margin-left:auto; }
#root #keyslist .row:hover{ background:var(--ui-raised); box-shadow:inset 3px 0 0 var(--acc); }

check:
{v:'VER',what:'Settings has one tab strip: Send play data is a chip of the section strip, the title tabs show only on the Send play data page',
 run:function(){
   if(typeof openSettings!=='function') return 'SKIP: no Settings here';
   var bad=[], tb, go, rec;
   try{
     openSettings('display'); tb=document.getElementById('settabs'); go=document.querySelector('#setlist .setjump button[data-go]');
     if(!tb) return 'SKIP: no tabs';
     if(getComputedStyle(tb).visibility!=='hidden') bad.push('the title tabs show on the Game page');
     if(!go) bad.push('no Send play data chip in the section strip');
     else {
       go.click(); rec=document.getElementById('spane_rec');
       if(!rec||rec.style.display==='none') bad.push('the chip did not open Send play data');
       if(getComputedStyle(tb).visibility==='hidden') bad.push('no way back on the Send play data page');
     }
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ openSettings('display'); }catch(_o){} try{ ['settingsmodal'].forEach(function(i){ var q=document.getElementById(i); if(q) q.classList.remove('on'); }); }catch(_k){} try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
